import sys
def solve(n, arr, queries):
    tree = [float('inf')] * (2 * n)
    for i in range(n): tree[n + i] = arr[i]
    for i in range(n - 1, 0, -1): tree[i] = min(tree[2*i], tree[2*i+1])
    def update(i, val):
        i += n; tree[i] = val
        while i > 1: i //= 2; tree[i] = min(tree[2*i], tree[2*i+1])
    def query(l, r):
        res = float('inf'); l += n; r += n + 1
        while l < r:
            if l & 1: res = min(res, tree[l]); l += 1
            if r & 1: r -= 1; res = min(res, tree[r])
            l >>= 1; r >>= 1
        return res
    out = []
    for type_, a, b in queries:
        if type_ == 1: update(a, b)
        else: out.append(str(query(a, b)))
    return "\n".join(out)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    arr = list(map(int, data[idx:idx+n])); idx += n
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        t,a,b = int(data[idx]),int(data[idx+1]),int(data[idx+2]); idx+=3
        queries.append((t,a,b))
    print(solve(n, arr, queries))

